    """Count numbers in the range with suffix s and all digits at most limit."""
    if not s or s[0] == "0" or any(not ch.isdigit() or int(ch) > limit for ch in s):
        return 0
    suffix_len = len(s)

    def count_prefixes_at_most(bound: str) -> int:
        """Count valid positive prefixes of this length <= the digit string."""
        length = len(bound)
        if length == 0:
            return 0
        total = 0
        for i, ch in enumerate(bound):
            digit = ord(ch) - 48
            minimum = 1 if i == 0 else 0
            remaining = length - i - 1
            choices = max(0, min(limit, digit - 1) - minimum + 1)
            total += choices * (limit + 1) ** remaining
            if digit < minimum or digit > limit:
                return total
        return total + 1

    def count_up_to(bound: int) -> int:
        if bound <= 0:
            return 0
        bound_text = str(bound)
        if suffix_len > len(bound_text):
            return 0
        total = 0

        # All shorter valid values, with prefixes of any allowed digits.
        for length in range(suffix_len, len(bound_text)):
            prefix_len = length - suffix_len
            if prefix_len == 0:
                total += 1
            else:
                total += limit * (limit + 1) ** (prefix_len - 1)

        prefix_len = len(bound_text) - suffix_len
        if prefix_len == 0:
            total += int(s <= bound_text)
        else:
            prefix_bound = bound_text[:prefix_len]
            prefixes = count_prefixes_at_most(prefix_bound)
            # The prefix equal to the bound prefix only works if the suffix is
            # no greater than the bound's remaining digits.
            if s > bound_text[prefix_len:]:
                prefix_is_valid = all(
                    1 <= int(ch) <= limit if i == 0 else 0 <= int(ch) <= limit
                    for i, ch in enumerate(prefix_bound)
                )
                if prefix_is_valid:
                    prefixes -= 1
            total += prefixes
        return total

    return count_up_to(finish) - count_up_to(start - 1)"}
